contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        bool repayDirect_,
        bool isCallback_
    ) public payable {
        require(loanToCollateral_ > 0, "zero ltc");
        require(duration_ > 0, "zero duration");

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_); if (__ESBMC_reverted()) return;

        bool activeBefore = c.isActive(reqID); if (__ESBMC_reverted()) return;

        bool reverted;
        c.clearRequest(reqID, repayDirect_, isCallback_); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool activeAfter = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(reverted == !activeBefore || activeAfter == false);
    }

    receive() external payable {}
}

