    }

    function _run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) internal {
        vm.assume(loanToCollateral_ > 0);
        vm.assume(duration_ > 0);
        uint256 reqID;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) returns (uint256 __r) { reqID = __r; } catch { return; }
        bool activeBefore;
        try c.isActive(reqID) returns (bool __r) { activeBefore = __r; } catch { return; }
        bool reverted;
        try c.clearRequest(reqID, repayDirect_, isCallback_) {
            reverted = false;
        } catch {
